const getRupsByMethodist = `-- name: GetRupsByMethodist :many
SELECT id, name, code, status, reason, course, study_form, study_year, type, total_hours, contacts, group_ids, methodist, teacher, exploration_note_id, disciplines, created_at, updated_at FROM rups WHERE methodist = $1 ORDER BY created_at DESC
`

func (q *Queries) GetRupsByMethodist(ctx context.Context, methodist pgtype.UUID) ([]Rup, error) {
	rows, err := q.db.Query(ctx, getRupsByMethodist, methodist)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Rup
	for rows.Next() {
		var i Rup
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Code,
			&i.Status,
			&i.Reason,
			&i.Course,
			&i.StudyForm,
			&i.StudyYear,
			&i.Type,
			&i.TotalHours,
			&i.Contacts,
			&i.GroupIds,
			&i.Methodist,
			&i.Teacher,
			&i.ExplorationNoteID,
			&i.Disciplines,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

